using UnityEditor;
using UnityEditor.SceneManagement;
using UnityEngine;

namespace PlayModeBootper
{
    [InitializeOnLoad]
    static class PlayModeBootperEditor
    {
        const string PrefKey = "PlayModeBootper_TargetSceneName";
        const string BootSceneName = "_Boot";

        // keep the previous playModeStartScene so we can restore it
        static SceneAsset _previousStartScene;

        static PlayModeBootperEditor()
        {
            EditorApplication.playModeStateChanged += OnPlayModeStateChanged;
        }

        static void OnPlayModeStateChanged(PlayModeStateChange state)
        {
            if (state == PlayModeStateChange.ExitingEditMode)
            {
                var active = EditorSceneManager.GetActiveScene();
                if (string.IsNullOrEmpty(active.path))
                {
                    Debug.LogWarning("[PlayModeBootper] Active scene has no path; aborting boot override.");
                    return;
                }

                // Save the active scene path so the boot scene can load it at runtime
                EditorPrefs.SetString(PrefKey, active.path);

                // Try to find the _Boot scene asset in the project
                string[] guids = AssetDatabase.FindAssets(BootSceneName + " t:Scene");
                SceneAsset bootAsset = null;
                foreach (var g in guids)
                {
                    string path = AssetDatabase.GUIDToAssetPath(g);
                    if (System.IO.Path.GetFileNameWithoutExtension(path) == BootSceneName)
                    {
                        bootAsset = AssetDatabase.LoadAssetAtPath<SceneAsset>(path);
                        break;
                    }
                }

                if (bootAsset == null)
                {
                    Debug.LogWarning("[PlayModeBootper] Couldn't find a scene named '_Boot' in the project. Play will proceed normally.");
                    return;
                }

                  // Ensure the boot scene has a BootLoader component instance so runtime can load the target scene
                  try
                  {
                      string bootPath = AssetDatabase.GetAssetPath(bootAsset);
                      // Open boot scene additively so we can inspect/edit it
                      var opened = EditorSceneManager.OpenScene(bootPath, OpenSceneMode.Additive);
                      bool hasBootLoader = false;
                      foreach (var root in opened.GetRootGameObjects())
                      {
                          if (root.GetComponentInChildren(typeof(BootLoader)) != null)
                          {
                              hasBootLoader = true;
                              break;
                          }
                      }

                      if (!hasBootLoader)
                      {
                          var go = new GameObject("BootLoader");
                          go.AddComponent<BootLoader>();
                          // Move the new object into the opened boot scene
                          UnityEngine.SceneManagement.SceneManager.MoveGameObjectToScene(go, opened);
                          EditorSceneManager.MarkSceneDirty(opened);
                          EditorSceneManager.SaveScene(opened);
                          Debug.Log("[PlayModeBootper] Added BootLoader component to _Boot scene.");
                      }

                      // Restore the previously active scene so we don't change the user's open scene
                      EditorSceneManager.OpenScene(active.path, OpenSceneMode.Single);
                  }
                  catch (System.Exception ex)
                  {
                      Debug.LogWarning($"[PlayModeBootper] Could not ensure BootLoader in _Boot scene: {ex.Message}");
                  }

                  _previousStartScene = EditorSceneManager.playModeStartScene;
                  EditorSceneManager.playModeStartScene = bootAsset;
                  Debug.Log($"[PlayModeBootper] PlayMode start scene set to '{BootSceneName}'. Target scene '{active.path}' saved.");
            }

            // When returning to the editor (play stopped) restore previous state and clear the pref
            if (state == PlayModeStateChange.EnteredEditMode || state == PlayModeStateChange.ExitingPlayMode)
            {
                try
                {
                    if (_previousStartScene != null)
                    {
                        EditorSceneManager.playModeStartScene = _previousStartScene;
                        _previousStartScene = null;
                    }
                    else
                    {
                        EditorSceneManager.playModeStartScene = null;
                    }
                }
                catch
                {
                    // ignore any issues restoring the start scene
                }

                if (EditorPrefs.HasKey(PrefKey))
                    EditorPrefs.DeleteKey(PrefKey);
            }
        }
    }
}

using System.Collections;
using UnityEngine;
using UnityEngine.SceneManagement;

public class BootLoader : MonoBehaviour
{
    const string PrefKey = "PlayModeBootper_TargetSceneName";

    IEnumerator Start()
    {
        // Only run this logic in the editor play session where the editor placed _Boot as the play scene
        #if UNITY_EDITOR
        string targetPath = UnityEditor.EditorPrefs.GetString(PrefKey, null);
        if (string.IsNullOrEmpty(targetPath))
        {
            Debug.LogWarning("[BootLoader] No target scene specified in EditorPrefs. Nothing to load.");
            yield break;
        }

        // Wait a frame for things to initialize
        yield return null;

        string targetName = System.IO.Path.GetFileNameWithoutExtension(targetPath);

        Debug.Log($"[BootLoader] Attempting to load target scene. Path: '{targetPath}', Name: '{targetName}'");

        // If the target scene is already loaded by name, just unload the boot scene
        if (SceneManager.GetSceneByName(targetName).isLoaded)
        {
            Debug.Log($"[BootLoader] Target scene '{targetName}' already loaded. Unloading _Boot.");
            var bootScene = SceneManager.GetSceneByName("_Boot");
            if (bootScene.IsValid() && bootScene.isLoaded)
                yield return SceneManager.UnloadSceneAsync(bootScene);
            yield break;
        }

        AsyncOperation op = null;

        // First try to load by name (works if scene is in Build Settings)
        try
        {
            op = SceneManager.LoadSceneAsync(targetName, LoadSceneMode.Additive);
            if (op != null)
                Debug.Log($"[BootLoader] Started LoadSceneAsync by name for '{targetName}'.");
        }
        catch (System.Exception ex)
        {
            Debug.LogWarning($"[BootLoader] LoadSceneAsync by name threw exception for '{targetName}': {ex.Message}");
            op = null;
        }

        // If couldn't start a normal load (e.g., scene not in Build Settings), fallback to Editor-only API to load by path in play mode
        if (op == null)
        {
            try
            {
                var loadParams = new LoadSceneParameters(LoadSceneMode.Additive);
                op = UnityEditor.SceneManagement.EditorSceneManager.LoadSceneAsyncInPlayMode(targetPath, loadParams);
                if (op != null)
                    Debug.Log($"[BootLoader] Started EditorSceneManager.LoadSceneAsyncInPlayMode for path '{targetPath}'.");
            }
            catch (System.Exception ex)
            {
                Debug.LogError($"[BootLoader] Failed to start Editor load for '{targetPath}': {ex.Message}");
                op = null;
            }
        }

        if (op == null)
        {
            Debug.LogError($"[BootLoader] Failed to start loading scene '{targetName}' (path '{targetPath}').");
            yield break;
        }

        while (!op.isDone)
            yield return null;

        // After load completes, find the loaded scene by name and activate it
        Scene loaded = SceneManager.GetSceneByName(targetName);
        if (loaded.IsValid() && loaded.isLoaded)
        {
            SceneManager.SetActiveScene(loaded);
            Debug.Log($"[BootLoader] Loaded and set active scene '{targetName}'. Unloading _Boot.");
        }
        else
        {
            Debug.LogError($"[BootLoader] Scene '{targetName}' was not found after load operation.");
        }

        // Unload the boot scene by name
        var boot = SceneManager.GetSceneByName("_Boot");
        if (boot.IsValid() && boot.isLoaded)
        {
            yield return SceneManager.UnloadSceneAsync(boot);
        }
        #endif
    }
}
